import { ok, fail } from './result.js';
import { invoiceTotals } from './invoices.js';
import { isValidDate } from './dates.js';

/**
 * Calculate the amount still owed on an invoice.
 * @param {{ payments?: Array<{ amount: number }> }} invoice
 * @returns {number} amount still owed (total minus payments)
 */
export function balanceDue(invoice) {
  const totals = invoiceTotals(invoice);
  const paid = (invoice.payments || []).reduce((sum, p) => sum + p.amount, 0);
  return Math.max(0, totals.total - paid);
}

/**
 * Record a payment on an issued or partially paid invoice.
 * @param {{ status: string, payments?: Array, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {{ amount: number, date: string }} payment
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function recordPayment(invoice, { amount, date }) {
  // Check if invoice is issued or partially paid
  if (invoice.status !== 'issued' && invoice.status !== 'partially_paid') {
    return fail('NOT_ISSUED');
  }

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  // Validate date
  if (!isValidDate(date)) {
    return fail('DATE_INVALID');
  }

  // Check for overpayment
  const owed = balanceDue(invoice);
  if (amount > owed) {
    return fail('OVERPAYMENT');
  }

  // Create new invoice with payment recorded
  const newInvoice = {
    ...invoice,
    payments: [...(invoice.payments || []), { amount, date }],
  };

  // Update status based on remaining balance
  const newOwd = balanceDue(newInvoice);
  if (newOwd === 0) {
    newInvoice.status = 'paid';
  } else if (newOwd < owed) {
    newInvoice.status = 'partially_paid';
  }

  return ok(newInvoice);
}

